&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;8&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;6&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;You are comfortable with technologies such as Kotlin/Spring Boot, Kubernetes, PostgreSQL&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt; and Azure cloud&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;What We Offer:&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;An &lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;unlimited &lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;contract with 30 vacation days.  &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Flexible, hybrid work:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt; You can work from home or come into the office on the schedule that works best for you. Feel like traveling and working from another location? No problem. Tune into meetings and work from abroad for up to 40 days per year. In addition, flex hours allow you to prioritize important moments in your day.  &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Attractive perks and benefits&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;: We offer a company pension scheme, language courses (English/German), and employee discounts with selected sustainable brands. Furthermore, our external partners in mental health support you in strengthening your mental health through anonymous private/group sessions.   &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Virtual Shares Program&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;: Participate in the success of GROPYUS through our Virtual Share Program.  &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;5&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Ownership&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;: You can truly make your mark with your work and contributions – on  all our organizational levels. Find your solutions, drive and test them.  &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;6&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;The chance to be part of something big&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;: Our mission is to rethink an entire industry. Join us in reinventing construction and fostering sustainable, affordable living.   &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;7&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;A diverse and enriching work environment&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;: Become a valued member of a wonderfully diverse team of individuals from over 50 countries. At GROPYUS we value inclusion above all, ensuring that everyone feels they belong – no matter their background. In this way, our differences become strengths that help us grow as a team. &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h4&gt;Join us on our mission to design buildings as continuously evolving products to create the most exciting and affordable experience for all. We build for people and conserve the resources of our planet.&lt;br&gt;&lt;br&gt;We can&#39;t wait to get to know you.&amp;nbsp;&lt;br&gt;For more information, visit our&amp;nbsp;&lt;a href=&quot;https://gropyus.com/&quot;&gt;website&lt;/a&gt;.&lt;/h4&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.com">Jobs in Germany</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;&lt;span data-olk-copy-source=&quot;MessageBody&quot;&gt;A career that’s the whole package!&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Conga, we’ve built a community where our colleagues can thrive. Here you’ll find opportunities to innovate and support growth through individual and team development, all within an environment where every voice is heard.&lt;/p&gt;
&lt;p&gt;&lt;span data-teams=&quot;true&quot;&gt;&lt;strong&gt;Conga&lt;/strong&gt; lines up commercial operations so companies run as connected, smarter businesses. By unifying the people and processes that drive commerce, Conga aligns pricing, quoting, contracting, rebates, and communications so teams stay in sync and buyers keep moving forward. The result is trusted decisions, consistent buyer experiences, and profitable growth. More than 10,000 customers worldwide, including over 50% of the Fortune 100®, trust Conga when commercial complexity is high and global impact is on the line.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;Location:&amp;nbsp;&lt;/strong&gt;Germany (remote)&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Reports to: &lt;/strong&gt;RVP Sales&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Languages: &lt;/strong&gt;native/C2 level German and English&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;A Quick Snapshot…..&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;As an Account Executive,&amp;nbsp;you&#39;ll&amp;nbsp;be at the forefront of our revenue growth strategy, spearheading efforts to uncover and nurture new business prospects while strengthening connections with our current clientele. Your role will involve deeply understanding client requirements, crafting personalized solutions, and ensuring top-notch customer satisfaction. Collaborating closely with Sales Engineering, Business/Sales Development, Marketing, Transformation Specialists,&amp;nbsp;Customer Success, Professional Services, Partners&amp;nbsp;and clients, your primary focus will be on&amp;nbsp;prospecting, managing and closing new business opportunities for enterprise-wide CONGA solutions with organizations across a variety of key strategic industries/verticals in the B2B space.&amp;nbsp;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Why it’s big deal…&amp;nbsp;&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;You&#39;ll have the chance to sell high-impact, mission-critical projects with substantial value, driving transformational change for our clients in Central Europe. Your role will involve skillfully crafting and implementing territory, account, and opportunity plans to optimize revenue within your assigned selling patch. You&#39;ll expertly manage sales opportunities throughout every stage of the cycle, ensuring success for both our clients and our company.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Are you the person we are looking for?  &lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Proven&amp;nbsp;track record.&lt;/strong&gt;  You have at least 5 years successful B2B technology Enterprise sales experience in the SaaS industry, in Central Europe.&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Proficiency&amp;nbsp;in revenue management principles is crucial.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;You have a consistent track record of&amp;nbsp;over achieving&amp;nbsp;quota and revenue targets. &amp;nbsp;&lt;/li&gt;
&lt;li&gt;You cultivate and&amp;nbsp;leverage&amp;nbsp;strategic relationships with partners to drive mutual business growth and success.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Knowledge and experience in general AI and machine learning can bring significant value. You understand how AI can enhance revenue management processes.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Hunter mentality.&amp;nbsp;&lt;/strong&gt;You&#39;ll&amp;nbsp;have the opportunity to unleash your inner hunter and drive our growth through relentless pursuit of new business opportunities. You thrive in a fast-paced environment,&amp;nbsp;leveraging&amp;nbsp;your strategic mindset and tenacity to&amp;nbsp;identify, pursue, and close deals with potential clients. The focus is 90%&amp;nbsp;new&amp;nbsp;business.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Solution Selling. &lt;/strong&gt;Collaborate with prospects and clients to understand their unique challenges and business goals. Present Conga&#39;s comprehensive suite of solutions and services that align with clients&#39; needs,&amp;nbsp;demonstrating&amp;nbsp;a deep understanding of how Conga can provide value.&amp;nbsp;&lt;br&gt;&lt;br&gt;&lt;strong&gt;Drive&lt;/strong&gt;.&amp;nbsp;You have the ability to successfully leverage resources and take initiative. The most successful Conga reps are the ones who stop at nothing to achieve success no matter the&amp;nbsp;circumstance.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Communication&lt;/strong&gt;: You have the ability to articulate complex technology concepts to a technical and non-technical audience.&amp;nbsp;You also have superb listening&amp;nbsp;skills&amp;nbsp;and you understand objections and overcome them by turning skeptics into enthusiastic new customers and brand ambassadors. You&amp;nbsp;possess&amp;nbsp;Excellent written and verbal communication skills.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Growth Mindset&lt;/strong&gt;. As the business landscape is constantly&amp;nbsp;evolving&amp;nbsp;you adapt to changes in market conditions, customer preferences, and competitive dynamics. You innovate and develop creative solutions to address challenges and capitalize on opportunities in the revenue management space.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Collaboration.&lt;/strong&gt; &amp;nbsp;You&#39;ll&amp;nbsp;work closely with cross-functional teams including Sales Engineering, Business Development, Marketing, and Customer Success to deliver exceptional value to our clients and drive mutual success. Together,&amp;nbsp;we&#39;ll&amp;nbsp;leverage&amp;nbsp;each other&#39;s&amp;nbsp;expertise&amp;nbsp;and insights to achieve our goals and surpass expectations.&amp;nbsp;You have the gravitas to lead a winning team,&amp;nbsp;leveraging&amp;nbsp;the strengths and skills of the organization to deliver profitable business to the organization.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What will give you an edge...&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Experience selling Revenue Lifecycle Management solutions with a good understanding of CPQ,&amp;nbsp;revenue optimization,&amp;nbsp;CLM, doc-gen and e-signature products.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Education and/or experience in Economics, Statistics, Mathematics, Accounting, Marketing, Finance, or Operations Research considered a plus.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;#LI-AM1&lt;/p&gt;
&lt;p&gt;#LI-Remote&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;Did we pique your interest? &lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;If this sounds like the kind of job you would love in the kind of environment where you would thrive, please click apply. &lt;span data-olk-copy-source=&quot;MessageBody&quot;&gt;We&#39;d love to hear from you! &lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Preferred Resume Format&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;We accept resumes in any format, we suggest using PDF or plain text. These formats help ensure that your resume’s formatting remains intact, making it easier for our recruiters to review your application promptly.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Don’t meet every requirement for the role?&lt;/strong&gt;&lt;strong&gt; &lt;/strong&gt;&lt;strong&gt; &lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Studies have shown that women and members of ethnic minorities are less likely to apply to jobs unless they meet every single qualification. At Conga we are dedicated to building a diverse, inclusive, and authentic workplace, so if you’re excited about this role but your experience doesn’t align perfectly with every qualification in the job description, we encourage you to apply anyway. You just might be the right candidate for this or other roles. &amp;nbsp;&lt;/p&gt;
&lt;div&gt;
&lt;section id=&quot;st-additionalInformation&quot; class=&quot;job-section&quot;&gt;
&lt;div&gt;
&lt;h2 class=&quot;title&quot;&gt;Additional Information&lt;/h2&gt;
&lt;/div&gt;
&lt;div class=&quot;wysiwyg&quot;&gt;
&lt;p&gt;Conga is proud to be an Equal Opportunity Employer and provides equal employment opportunities to all employees and applicants regardless of race, color, religion, gender, gender identity, age, national origin, disability, parental or pregnancy status, marriage and civil partnership, sexual orientation, veteran status, or any other characteristic protected by law. We understand interviewing can be stressful for those with disabilities. If reasonable accommodation is needed to allow you to show us your best self, please let your recruiter know as soon as possible. All your information will be kept confidential according to EEO guidelines. Conga is not open to third party solicitation or resumes for our posted FTE positions. Resumes received from third party agencies that are unsolicited will be considered complimentary.&lt;/p&gt;
&lt;/div&gt;
&lt;/section&gt;
&lt;/div&gt;
&lt;section class=&quot;job-apply print-hidden&quot;&gt;&lt;/section&gt;
&lt;p&gt;&lt;strong&gt;Conga&#39;s Applicant Privacy Statement&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The information you provide during the application process will be used in accordance with Conga’s Applicant Privacy Statement (&lt;a href=&quot;https://conga.com/applicant-privacy-statement&quot;&gt;https://conga.com/applicant-privacy-statement&lt;/a&gt;). By submitting your application, you acknowledge and agree to the terms outlined in this privacy statement.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;/div&gt;<p>Find more <a href="https://www.arbeitnow.com/english-speaking-jobs">English Speaking Jobs in Germany</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;span class=&quot;fabric-text-color-mark&quot; data-renderer-mark=&quot;true&quot; data-text-custom-color=&quot;#36b37e&quot;&gt;IDnow is a&lt;strong&gt; leader in digital identity and fraud prevention in Europe&lt;/strong&gt; with a mission to transform trust into the most powerful asset in the digital world, empowering enterprises with &lt;strong&gt;AI-driven, SaaS-based identity solutions that deliver scalable security, adaptive compliance, and real-time fraud prevention&lt;/strong&gt;.&lt;/span&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt; &lt;/strong&gt;&lt;span class=&quot;fabric-text-color-mark&quot; data-renderer-mark=&quot;true&quot; data-text-custom-color=&quot;#36b37e&quot;&gt;Through its broad portfolio of digital identity and fraud prevention solutions, IDnow establishes, maintains and enriches trust throughout the customer journey, ensuring businesses can confidently and securely operate while leveraging digital identity to drive growth, security and scalability. &lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;fabric-text-color-mark&quot; data-renderer-mark=&quot;true&quot; data-text-custom-color=&quot;#36b37e&quot;&gt;The company has &lt;strong&gt;offices in Germany, United Kingdom, Romania and France&lt;/strong&gt;, and is backed by renowned institutional investors, including Corsair Capital and Seventure Partners. Its &lt;strong&gt;portfolio of international clients spans a wide range of end markets&lt;/strong&gt; including financial services, telecommunications, travel &amp;amp; mobility, gaming, and other industries.&lt;/span&gt;&lt;/p&gt;
&lt;hr&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;/div&gt;&lt;p style=&quot;text-align: center;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;This position is based in Berlin/Munich, Germany or Rennes, France.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335551550&amp;quot;:2,&amp;quot;335551620&amp;quot;:2,&amp;quot;335557856&amp;quot;:16777215}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;text-align: center;&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;IDnow is looking for&amp;nbsp;&lt;strong&gt;Product Owner – Trust Services (f/m/d) &lt;/strong&gt;to own the product direction, backlog and outcomes for a technical product area within IDnow’s Digital Identity and Trust Services portfolio. Working with a dedicated Scrum Team, this role turns customer, operational, regulatory and engineering input into a clear product goal, an ordered backlog and valuable, usable increments that can be released and operated safely.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The most critical aspect of this role is serving as the accountable product interface between the Trust Services domain and Engineering: understanding the system boundaries, APIs, integrations, data flows and non-functional requirements well enough to make sound trade-offs, remove ambiguity and ensure that security, privacy, resilience, auditability and regulatory obligations are built into the product from the beginning.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Key Responsibilities&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;Own the product goal, &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;roadmap&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt; and backlog&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;: &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;prioritize by&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt; value, risk, &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;dependencies&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt; and learning; keep decisions transparent.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;Drive Scrum outcomes&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;: lead refinement, support Planning and Reviews, clarify Sprint Goals, and use delivery metrics to improve flow.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;Turn needs into buildable requirements&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;: define user/system journeys, domain concepts, business rules, APIs, data states, errors, acceptance &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;criteria&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt; and testable non-functional requirements&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt; – &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;without over-prescribing implementation.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;Partner on solution quality&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;: work with Engineering, Architecture, Security, QA and Operations on service boundaries, technical debt, &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;scalability, performance, availability, resilience, observability, &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;incidents&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt; and operational readiness.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;Own data, &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;integration&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt; and lifecycle design&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;: govern identity and &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;audit-data&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt; flows, access, &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;protection&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt; and retention; shape secure, interoperable APIs, including authentication, encryption, versioning, error &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;handling&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt; and documentation.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;Support releases and continuous improvement&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;: define readiness, migrations, cutovers, deprecation, feature &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;flags&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt; and rollback; &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;participate&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt; in incident reviews and prioritize recurring quality, &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;security&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt; and operational issues.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;Translate regulation into product decisions&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;: apply eIDAS2, EUDI Wallet, QES, QEAA/EAA, identity-proofing and trust-service requirements with Compliance, Legal, Risk and Trust Services SMEs, tracking adoption, reliability, quality, delivery &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;flow&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt; and compliance readiness.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Collaborate&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; across functions:&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt; &lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;align &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;with Scrum Team&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;s&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;, Engineering leadership, Architecture, Security, SRE/Operations, Trust Services, Product, Compliance/Legal/Risk/Data Protection, Commercial and Customer Success, as well as relevant partners, relying parties and standards bodies.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Preferred Experience&lt;/span&gt;&lt;/strong&gt; &lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;4+ years of experience in Product Ownership, Technical Product Management, Business Analysis or similar roles in software and service delivery, including direct responsibility for backlog quality and product outcomes.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:567,&amp;quot;335559991&amp;quot;:283,&amp;quot;469777462&amp;quot;:[720,284],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[0,8]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Hands-on experience working in Scrum or a comparable agile delivery model: ability to define a Product Goal, order a Product Backlog, write clear product backlog items, set acceptance criteria, participate in refinement and reviews, and make timely scope and priority decisions.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:567,&amp;quot;335559991&amp;quot;:283,&amp;quot;469777462&amp;quot;:[720,284],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[0,8]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Strong technical fluency in modern software products and integrations, including REST APIs, JSON/Open API, authentication and authorization, OAuth2/OIDC concepts, webhooks or event streams, data models, service boundaries, API lifecycle and backward-compatible change.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:567,&amp;quot;335559991&amp;quot;:283,&amp;quot;469777462&amp;quot;:[720,284],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[0,8]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Demonstrable experience working with regulated software and services, translating regulatory, security, privacy and audit requirements into actionable product requirements and delivery decisions, while balancing compliance, customer value, usability, scalability and time to market.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:567,&amp;quot;335559991&amp;quot;:283,&amp;quot;469777462&amp;quot;:[720,284],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[0,8]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Practical understanding of secure software and service delivery: threat and risk thinking, software security, access control, encryption, secrets and key management, vulnerability handling, logging/monitoring, incident response, resilience and software supply-chain considerations.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:567,&amp;quot;335559991&amp;quot;:283,&amp;quot;469777462&amp;quot;:[720,284],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[0,8]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Practical understanding of data lifecycle and privacy-by-design for identity and trust services, including data minimization, purpose limitation, sensitive evidence, retention and deletion, evidence, archival, data residency, audit trails and access transparency.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:567,&amp;quot;335559991&amp;quot;:283,&amp;quot;469777462&amp;quot;:[720,284],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[0,8]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Ability to work with Engineering on system-level trade-offs without needing to be the implementing engineer, and to distinguish product decisions, architecture decisions, implementation choices, technical debt and operational risk.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:567,&amp;quot;335559991&amp;quot;:283,&amp;quot;469777462&amp;quot;:[720,284],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[0,8]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience with service operations and lifecycle management, including release readiness, SLO or service-quality thinking, incident triage, post-incident learning, customer-impact assessment, migration, deprecation and support enablement.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:567,&amp;quot;335559991&amp;quot;:283,&amp;quot;469777462&amp;quot;:[720,284],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[0,8]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience in regulated industries (e.g., financial services, telecom, public sector, payments, KYC/AML, digital identity, electronic signatures, PKI or trust services) is a strong plus, as is familiarity with eIDAS2, EUDI Wallets, ETSI standards or QTSP operating models.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:567,&amp;quot;335559991&amp;quot;:283,&amp;quot;469777462&amp;quot;:[720,284],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[0,8]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
